{
  "title": "星尘迷雾",
  "scene": "你被困在废弃的太空站中，四周弥漫着朦胧的星尘，模糊了你的视线。你发现了一台通讯器，但屏幕显示着故障代码：“E501”。旁边有一张纸条，上面写着：“星尘遮蔽光，寻找暗处明。”你面前有两个房间和一台显微镜，显微镜内嵌着一只微型光谱仪，显示着淡淡的蓝色。你必须找到一个方法修复通讯器，才能联系到救援队。",
  "goal": "修复通讯器，联系到救援队",
  "clue": "线索位于纸条提示中：‘星尘遮蔽光，寻找暗处明’，显微镜和微型光谱仪显示蓝色",
  "choices": [
    {"id": "A", "text": "使用显微镜观察蓝色光谱", "outcome": "显微镜显示光谱线条清晰，但没有进一步线索。", "result": "partial", "next": "retry"},
    {"id": "B", "text": "进入左侧房间，寻找其他修复工具", "outcome": "房间内没有找到任何有用的工具，反而发现了一堆废弃的零件。", "result": "fail", "next": "retry"},
    {"id": "C", "text": "检查右方房间，利用纸条上的提示", "outcome": "在右方房间内找到一本维修手册，上面标明遇到E501故障时，需要使用蓝色光谱进行校正。通过显微镜内嵌的微型光谱仪，读取了相应的蓝色光谱，并输入通讯器中，成功修复了通讯器。", "result": "success", "next": "next_level"}
  ]
}
